\section{Introduction}

\subsection{Motivation}
The min-plus (tropical) semiring $(\RR \cup \{+\infty\}, \min, +)$ replaces addition by minimum and multiplication by addition. Its linear algebra is the algebra of shortest paths, of discrete-event scheduling, and of the combinatorial degenerations studied in tropical geometry. It is also \emph{piecewise linear rather than linear}, and this has motivated proposals to build cryptographic primitives on min-plus operations, on the intuition that classical algebraic cryptanalysis has no obvious purchase there.

We analyse the simplest such primitive. Fix a key $A \in \RR^{r \times k}$; a message is a vector $m \in \RR^k$; its digest is the min-plus matrix--vector product
\[
D_A(m)_i = \min_j (m_j + A_{ij}), \qquad i = 1,\dots,r .
\]
Compression corresponds to $r < k$. The design hope is that the destruction of information at each $\min$ makes the map hard to invert and hard to collide.

Our thesis is that this hope fails for a reason that is not algebraic but convex-geometric. The map $D_A$ is a concave piecewise linear map whose linearity domains are indexed by the choice of an active coordinate for each component. Each fiber is therefore a polyhedral complex, and the right question is: \emph{what is the recession cone of a fiber cell?} Once asked, it is answered completely, and the answer is fatal for the primitive.

\subsection{Contributions}
\begin{enumerate}
\item \textbf{Universal collision cone} (Theorem~\ref{thm:univ}): $\dim \Span \mathcal{C}_A(m) \ge k-r$ for every $A$ and $m$.
\item \textbf{Exact cone under general position} (Theorems~\ref{thm:exactcone} and \ref{thm:exactdim}), with non-vacuity (Proposition~\ref{prop:nonvac}), openness with explicit modulus (Theorem~\ref{thm:open}) and necessity of strictness (Proposition~\ref{prop:tie}).
\item \textbf{Hitting-set duality} (Theorems~\ref{thm:local}, \ref{thm:hit}, \ref{thm:tau}) and refutation of the transversal formulation (Proposition~\ref{prop:sdr}).
\item \textbf{Collapse of the bounded-alphabet defence} (Theorems~\ref{thm:twoletter}, \ref{thm:intform}) with sharpness (Theorem~\ref{thm:sharp}).
\item \textbf{Canonical inversion} (Theorems~\ref{thm:inv}, \ref{thm:box}), including the box-constrained case.
\end{enumerate}

\section{Setting and notation}

Throughout, $k \ge 1$ and $r \ge 0$ are integers, $A \in \RR^{r\times k}$ is a \emph{key family}, and messages are vectors $m \in \RR^k$. Inequalities between vectors are coordinatewise.

\begin{definition}[Digest]
The \emph{$r$-component min-plus digest} of $m$ under $A$ is $D_A(m)_i = \min_{1 \le j \le k}(m_j + A_{ij})$.
\end{definition}

Two facts are used constantly: $D_A(m)_i \le m_j + A_{ij}$ for every $j$, and $c \le D_A(m)_i$ whenever $c \le m_j + A_{ij}$ for all $j$. The minimum is attained since $k$ is finite.

\begin{definition}[Active set]
For a component $i$, $\Act_A(m,i) = \{ j : m_j + A_{ij} = D_A(m)_i \} \ne \emptyset$. Its elements are \emph{active} coordinates, or \emph{certificates} for component $i$.
\end{definition}

\begin{definition}[Collision cone]
The \emph{collision cone} at $m$ is
\[
\mathcal{C}_A(m) = \{ v \in \RR^k : D_A(m+sv) = D_A(m) \text{ for all } s \ge 0 \} .
\]
\end{definition}

$\mathcal{C}_A(m)$ is a closed cone containing $0$, and is precisely the recession cone of the polyhedral cell of the fiber $D_A^{-1}(D_A(m))$ containing $m$: the directions along which one may travel to infinity without leaving the fiber.

\begin{definition}[Collision support]
A set $S \subseteq \{1,\dots,k\}$ is a \emph{collision support at $m$} if $D_A(m+t) = D_A(m)$ for every $t \ge 0$ vanishing off $S$. Write $\Cone(S) = \{ v \ge 0 : v_j = 0 \ \forall j \notin S\}$ and $V_S = \{v : v_j = 0\ \forall j \notin S\}$.
\end{definition}

If $S$ is a collision support then $\Cone(S) \subseteq \mathcal{C}_A(m)$, since $sv \in \Cone(S)$ for $s \ge 0$, $v \in \Cone(S)$.

\section{Two elementary lemmas}

\begin{lemma}[Monotonicity]\label{lem:mono}
If $m \le m'$ then $D_A(m)_i \le D_A(m')_i$ for every $i$.
\end{lemma}
\begin{proof}
For every $j$, $D_A(m)_i \le m_j + A_{ij} \le m'_j + A_{ij}$; take the minimum over $j$.
\end{proof}

\begin{lemma}[Untouched-certificate invariance]\label{lem:cert}
Let $t \ge 0$ and let $i$ have a certificate $j_0 \in \Act_A(m,i)$ with $t_{j_0} = 0$. Then $D_A(m+t)_i = D_A(m)_i$.
\end{lemma}
\begin{proof}
$D_A(m+t)_i \le (m+t)_{j_0} + A_{ij_0} = m_{j_0} + A_{ij_0} = D_A(m)_i$; conversely $(m+t)_j + A_{ij} \ge m_j + A_{ij} \ge D_A(m)_i$ for all $j$.
\end{proof}

Lemma~\ref{lem:cert} is the engine of every collision result: \emph{an increase that spares at least one certificate of every component is invisible to the digest.} Lemma~\ref{lem:mono} drives the inversion results.

\section{The universal collision cone}

\begin{proposition}[Free coordinates]\label{prop:free}
For every $A$ and $m$ there is a collision support $S$ with $|S| \ge k - r$.
\end{proposition}
\begin{proof}
Choose a certificate $p(i) \in \Act_A(m,i)$ for each $i$ and set $S = \{1,\dots,k\} \setminus p(\{1,\dots,r\})$, so $|S| \ge k - r$. If $t \ge 0$ vanishes off $S$ then $t_{p(i)} = 0$ for every $i$, and Lemma~\ref{lem:cert} applies componentwise.
\end{proof}

\begin{lemma}\label{lem:dims}
$\dim V_S = |S|$ and $\Span \Cone(S) = V_S$.
\end{lemma}
\begin{proof}
$V_S$ is the kernel of the surjective restriction $\RR^k \to \RR^{S^c}$, so $\dim V_S = k - |S^c| = |S|$. For the span, $\Cone(S) \subseteq V_S$ is clear, and any $v \in V_S$ splits as $v = v^+ - v^-$ with $v^{\pm}_j = \max(\pm v_j, 0)$, both in $\Cone(S)$.
\end{proof}

\begin{theorem}[Universal lower bound]\label{thm:univ}
For every $A \in \RR^{r \times k}$ and every $m \in \RR^k$,
\[
\dim \Span \mathcal{C}_A(m) \;\ge\; k - r .
\]
\end{theorem}
\begin{proof}
With $S$ from Proposition~\ref{prop:free}, $V_S = \Span \Cone(S) \subseteq \Span \mathcal{C}_A(m)$ and $\dim V_S = |S| \ge k-r$ by Lemma~\ref{lem:dims}.
\end{proof}

\begin{lemma}[Unused coordinate]\label{lem:unused}
If $r < k$ then for every $A$ and $m$ there is a coordinate $q$ such that every component has a certificate $j \ne q$.
\end{lemma}
\begin{proof}
Choose certificates $p(i)$; the image has at most $r < k$ elements, so some $q$ lies outside it.
\end{proof}

\begin{lemma}[Bump invariance]\label{lem:bump}
If $q$ is unused at $m$ and $d \ge 0$ then $D_A(m + d\,e_q) = D_A(m)$.
\end{lemma}
\begin{proof}
$t = d\,e_q$ is nonnegative and vanishes at a certificate of each component; apply Lemma~\ref{lem:cert}.
\end{proof}

\begin{corollary}[Universal collisions]
If $r < k$ then for every $A$ and every $m$ there is $m' \ne m$ with $D_A(m') = D_A(m)$; one may take $m' = m + e_q$ for an unused coordinate $q$.
\end{corollary}

\section{Exact dimension in general position}

\begin{definition}[Strict minimizers]
A map $p : \{1,\dots,r\} \to \{1,\dots,k\}$ is a \emph{strict minimizer system} for $(A,m)$ if $D_A(m)_i < m_j + A_{ij}$ for every $i$ and every $j \ne p(i)$; equivalently $\Act_A(m,i) = \{p(i)\}$ for all $i$.
\end{definition}

\begin{theorem}[Exact cone]\label{thm:exactcone}
Assume $r \ge 1$ and let $p$ be a strict minimizer system for $(A,m)$. Then
\[
\mathcal{C}_A(m) = \bigl\{\, v \in \RR^k : v_j \ge 0 \ \forall j, \ v_{p(i)} = 0 \ \forall i \,\bigr\}.
\]
\end{theorem}
\begin{proof}
($\supseteq$) If $v \ge 0$ with $v_{p(i)} = 0$, then for $s \ge 0$ the displacement $sv$ is nonnegative and spares the certificate $p(i)$ of component $i$; Lemma~\ref{lem:cert} applies.

($\subseteq$) Let $v \in \mathcal{C}_A(m)$, fix a component $i$ and set $c = D_A(m)_i$.

\emph{No coordinate may decrease.} Suppose $v_q < 0$. Put $s = (m_q + A_{iq} - c + 1)/(-v_q) \ge 0$, so $s v_q = c - m_q - A_{iq} - 1$ and
\[
D_A(m + sv)_i \le m_q + s v_q + A_{iq} = c - 1 < c = D_A(m+sv)_i,
\]
a contradiction. Hence $v \ge 0$.

\emph{Certified coordinates are frozen.} Suppose $v_{p(i)} > 0$. Strictness yields a uniform gap $g = \min_{j \ne p(i)} \min(1, m_j + A_{ij} - c) > 0$. Let $M = 1 + \max_j |v_j|$, $s = g/(2M)$ so that $sM = g/2$, and $d = \min(g/2,\ s v_{p(i)}) > 0$. For $j = p(i)$: $(m+sv)_{p(i)} + A_{ip(i)} = c + s v_{p(i)} \ge c+d$. For $j \ne p(i)$: $m_j + A_{ij} \ge c + g$ and $|s v_j| \le sM = g/2$, so $(m+sv)_j + A_{ij} \ge c + g/2 \ge c+d$. Hence $D_A(m+sv)_i \ge c + d > c$, contradicting $v \in \mathcal{C}_A(m)$.
\end{proof}

\begin{theorem}[Exact recession dimension]\label{thm:exactdim}
Assume $r \ge 1$, let $p$ be a strict minimizer system for $(A,m)$, and suppose $p$ is injective. Then $\dim \Span \mathcal{C}_A(m) = k - r$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:exactcone}, $\mathcal{C}_A(m) = \Cone(S)$ with $S$ the complement of $p(\{1,\dots,r\})$, of cardinality $k-r$ by injectivity; apply Lemma~\ref{lem:dims}.
\end{proof}

\begin{proposition}[Non-vacuity]\label{prop:nonvac}
For every $r \le k$ there is a key with an injective strict minimizer system at $m = 0$: take $A_{ij} = 0$ if $j = \iota(i)$ and $A_{ij} = 1$ otherwise, for any injection $\iota$. Then $D_A(0)_i = 0$ and $p = \iota$ is a strict minimizer system.
\end{proposition}

\begin{theorem}[Openness of the generic locus]\label{thm:open}
Suppose $p$ is a strict minimizer system for $(A,m)$ with uniform gap $g > 0$, i.e.\ $m_{p(i)} + A_{ip(i)} + g \le m_j + A_{ij}$ for all $i$ and all $j \ne p(i)$. If $|A'_{ij} - A_{ij}| < g/4$ and $|m'_j - m_j| < g/4$ for all $i,j$, then $p$ is a strict minimizer system for $(A',m')$.
\end{theorem}
\begin{proof}
Fix $i$ and $j \ne p(i)$. Since $D_{A'}(m')_i \le m'_{p(i)} + A'_{ip(i)}$ it suffices to show $m'_{p(i)} + A'_{ip(i)} < m'_j + A'_{ij}$. Each of the four perturbations moves its term by less than $g/4$, so the left side is below $m_{p(i)} + A_{ip(i)} + g/2$ and the right side above $m_j + A_{ij} - g/2 \ge m_{p(i)} + A_{ip(i)} + g/2$.
\end{proof}

\begin{proposition}[Strictness is necessary]\label{prop:tie}
With $k = 2$, $r = 1$, $A = 0$ and $m = 0$, so that $D(m) = \min(m_1,m_2)$, the collision cone spans $\RR^2$, of dimension $2 > k-r = 1$.
\end{proposition}
\begin{proof}
$D_A(0) = 0$ and both coordinates are active, so for either basis vector $e_q$ and any $s \ge 0$ the other coordinate is an untouched certificate; Lemma~\ref{lem:cert} gives $s e_q \in \mathcal{C}_A(0)$, and $e_1, e_2$ span $\RR^2$.
\end{proof}

\section{Hitting-set duality and the true security parameter}

\begin{theorem}[Exact local criterion]\label{thm:local}
A set $S$ is a collision support at $m$ if and only if every component retains an active coordinate outside $S$:
\[
S \text{ is a collision support} \iff \forall i\ \exists j \notin S,\ j \in \Act_A(m,i).
\]
\end{theorem}
\begin{proof}
($\Leftarrow$) Lemma~\ref{lem:cert}. ($\Rightarrow$) Suppose $\Act_A(m,i) \subseteq S$ for some $i$ and let $c = D_A(m)_i$. Every $j \notin S$ has $m_j + A_{ij} > c$, so
\[
\varepsilon = \min_j \begin{cases} 1, & j \in S,\\ \min(1,\ m_j + A_{ij} - c), & j \notin S \end{cases}
\]
is positive and $m_j + A_{ij} \ge c + \varepsilon$ for $j \notin S$. Let $t = \varepsilon \mathbf{1}_S$. For $j \in S$, $(m+t)_j + A_{ij} \ge c + \varepsilon$; for $j \notin S$, $(m+t)_j + A_{ij} = m_j + A_{ij} \ge c + \varepsilon$. Hence $D_A(m+t)_i \ge c + \varepsilon > c$.
\end{proof}

\begin{definition}[Hitting number]
A \emph{hitting set} of $(A,m)$ is a set $H$ meeting every active set. The \emph{hitting number} $\tau(A,m)$ is the least cardinality of a hitting set: the vertex-cover number of the hypergraph whose edges are the active sets. It is well defined since $\{1,\dots,k\}$ is a hitting set.
\end{definition}

Theorem~\ref{thm:local} says exactly: \emph{$S$ is a collision support iff $S^c$ is a hitting set.}

\begin{theorem}[Hitting-set criterion]\label{thm:hit}
For $0 \le d \le k$, a collision support of size at least $d$ exists if and only if $(A,m)$ admits a hitting set of size at most $k-d$.
\end{theorem}
\begin{proof}
If $S$ is a collision support with $|S| \ge d$ then $S^c$ is a hitting set of size $\le k-d$; conversely if $H$ is a hitting set with $|H| \le k-d$ then $H^c$ is a collision support of size $\ge d$.
\end{proof}

\begin{proposition}[The transversal formulation is false]\label{prop:sdr}
Let $k = r = 2$, $m = 0$, and let both rows of $A$ equal $(0,1)$. Then $D_A(0) = (0,0)$ and $\Act_A(0,1) = \Act_A(0,2) = \{1\}$, so the active family has no system of distinct representatives; nevertheless $S = \{2\}$ is a collision support, giving a one-dimensional collision cone.
\end{proposition}
\begin{proof}
Both components attain their minimum $0$ at coordinate $1$ only, since coordinate $2$ contributes $0 + 1 = 1 > 0$. A transversal would force $f(1) = f(2) = 1$, contradicting injectivity. Since $\{1\} \not\subseteq \{2\}$, Theorem~\ref{thm:local} shows $\{2\}$ is a collision support.
\end{proof}

A transversal demands \emph{distinct} certificates for distinct components, whereas the geometry only demands that each component keep \emph{some} certificate outside $S$; sharing is allowed, and sharing is exactly what makes $\tau$ small and the cone large.

\begin{lemma}\label{lem:taur}
$\tau(A,m) \le r$ for all $A,m$.
\end{lemma}
\begin{proof}
The image of any choice function $i \mapsto p(i) \in \Act_A(m,i)$ is a hitting set of size at most $r$.
\end{proof}

\begin{theorem}[Maximal coordinate cone has dimension exactly $k-\tau$]\label{thm:tau}
The set $\{|S| : S \text{ a collision support at } m\}$ has greatest element $k - \tau(A,m)$. Consequently $\dim \Span \mathcal{C}_A(m) \ge k - \tau(A,m)$.
\end{theorem}
\begin{proof}
Attainment: if $|H| = \tau$ is a minimum hitting set then $H^c$ is a collision support of size $k-\tau$. Upper bound: if $S$ is a collision support then $S^c$ is a hitting set, so $\tau \le k - |S|$. The dimension statement follows from Lemma~\ref{lem:dims}.
\end{proof}

Since $\tau \le r$ (Lemma~\ref{lem:taur}), Theorem~\ref{thm:tau} refines Theorem~\ref{thm:univ}, strictly so whenever active sets overlap. We therefore propose $\tau(A,m)$, not $r$, as the \emph{local security parameter} of a min-plus digest.

\section{No bounded-alphabet threshold}

A natural defence restricts messages to a finite alphabet, on the intuition that the escaping ray must leave the legal message space and that the cut-off is governed by a \emph{key-spread} parameter such as $\max_{i,j}A_{ij} - \min_{i,j}A_{ij}$. We refute this: the correct threshold is two letters, with no dependence on the key.

\begin{theorem}[Two-letter collision]\label{thm:twoletter}
Let $r < k$, let $A \in \RR^{r\times k}$ be arbitrary, and let $a < b$ be reals. Then there exist distinct $m, m' \in \{a,b\}^k$ with $D_A(m) = D_A(m')$.
\end{theorem}
\begin{proof}
Let $m$ be the constant message equal to $a$. By Lemma~\ref{lem:unused} some coordinate $q$ is unused at $m$. Put $m' = m + (b-a)e_q$; both messages lie in $\{a,b\}^k$ and differ at $q$. By Lemma~\ref{lem:bump} with $d = b - a \ge 0$, $D_A(m') = D_A(m)$.
\end{proof}

The construction involves no quantity derived from $A$: no key-spread parameter can govern collision resistance, and the colliding ray needs to travel exactly one letter.

\begin{theorem}[Integer form]\label{thm:intform}
Let $r < k$, let $A$ have integer entries and let $B \ge 1$ be an integer. Then there are distinct $m,m' \in \{0,1,\dots,B\}^k$ with $D_A(m) = D_A(m')$.
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:twoletter} with $a = 0$, $b = 1$: the messages are the zero vector and the indicator of an unused coordinate.
\end{proof}

Over a one-letter alphabet the digest is vacuously injective, so the threshold $2$ cannot be lowered. The hypothesis $r < k$ is also necessary.

\begin{theorem}[Sharpness in $r$]\label{thm:sharp}
For every $B \in \RR$ and every $k$ there is $A \in \RR^{k\times k}$ whose digest is injective on $[0,B]^k$: take $A_{ij} = 0$ if $i = j$ and $A_{ij} = B+1$ otherwise; then $D_A(m)_i = m_i$ for all $m \in [0,B]^k$.
\end{theorem}
\begin{proof}
Taking $j = i$ gives $D_A(m)_i \le m_i$. For $j \ne i$, $m_j + A_{ij} = m_j + B + 1 \ge B+1 > B \ge m_i$, so no off-diagonal term wins; hence $D_A(m)_i = m_i$.
\end{proof}

The transition therefore sits exactly at $r = k$, and the injective examples there are essentially copies of the message: there is no compressing regime in which the min-plus digest resists collisions, over any alphabet.

\section{Canonical inversion and constrained mining}

Given $y \in \RR^r$, we seek $m$ with $D_A(m) = y$ --- the analogue of \emph{mining}. Naively the system is disjunctive: each equation splits into $k$ linear regions according to which coordinate is active, giving $k^r$ patterns. No enumeration is needed.

\begin{definition}[Canonical candidate]
For $r \ge 1$ and $y \in \RR^r$ set $m^\star_j = \max_{1 \le i \le r}(y_i - A_{ij})$. Equivalently $m^\star$ is the coordinatewise least vector satisfying all inequality constraints $m_j + A_{ij} \ge y_i$: indeed $m^\star_j \le m_j$ iff $y_i \le m_j + A_{ij}$ for all $i$.
\end{definition}

\begin{theorem}[One-shot inversion]\label{thm:inv}
For $r \ge 1$, a preimage of $y$ exists if and only if $D_A(m^\star) = y$. Moreover $m^\star$ is then the coordinatewise least element of the fiber.
\end{theorem}
\begin{proof}
($\Leftarrow$) trivial. ($\Rightarrow$) Let $D_A(m) = y$. For all $i,j$, $y_i = D_A(m)_i \le m_j + A_{ij}$, so $m^\star \le m$. By definition $y_i \le m^\star_j + A_{ij}$ for all $j$, hence $y_i \le D_A(m^\star)_i$; and by Lemma~\ref{lem:mono}, $D_A(m^\star)_i \le D_A(m)_i = y_i$.
\end{proof}

\begin{theorem}[Box-constrained mining]\label{thm:box}
Let $L, U \in \RR^k$ and $w_j = \max(m^\star_j, L_j)$. Then a message $m$ with $L \le m \le U$ and $D_A(m) = y$ exists if and only if $w \le U$ and $D_A(w) = y$.
\end{theorem}
\begin{proof}
($\Leftarrow$) $w$ is a witness since $w \ge L$. ($\Rightarrow$) If $m$ is a constrained solution then $m^\star \le m$ by Theorem~\ref{thm:inv} and $L \le m$, so $w \le m \le U$. Also $y_i \le m^\star_j + A_{ij} \le w_j + A_{ij}$ for all $j$, whence $y_i \le D_A(w)_i$, while monotonicity gives $D_A(w)_i \le D_A(m)_i = y_i$.
\end{proof}

\begin{corollary}
Restricting the message space to a box does not make tropical preimage search harder: it remains a one-shot test. Hence any hardness of a constrained mining problem must come from constraint families that are not upward closed, never from the min-plus structure itself.
\end{corollary}

\section{Computational evidence}

The theory was cross-checked on integer instances by brute-force enumeration of coordinate subsets and of hitting numbers.

For $A$ with rows $(0,3,5,2)$, $(4,1,7,6)$, $(9,8,2,3)$ at $m = 0$: the digest is $(0,1,2)$, active sets are $\{1\},\{2\},\{3\}$, so $\tau = 3$ and the maximal coordinate cone has dimension $1 = k-\tau = k-r$, the generic case. For rows $(0,0,5,2)$, $(0,1,7,6)$ at $m=0$: active sets $\{1,2\}$ and $\{1\}$ give $\tau = 1$ and cone dimension $3 > k-r = 2$. For both rows $(0,1)$ at $m=0$: $\tau = 1$ and cone dimension $1 > k-r = 0$, the transversal counterexample.

Over $400$ pseudorandom instances with $k = 4$ and $r \in \{1,2,3\}$, the maximal coordinate cone dimension equalled $k - \tau$ in every instance and dominated $k - r$ in every instance. Over $50$ pseudorandom instances with $k = 3$ and box $\{0,\dots,12\}^3$, exhaustive search for a boxed preimage agreed in every instance with the one-shot test at $\max(m^\star, 0)$.

\section{Discussion}

\textbf{Collision resistance is impossible below $r = k$.} Through \emph{every} message there is a $(k-r)$-dimensional cone of colliding directions, and over a two-letter alphabet an explicit colliding pair is produced by inspection. Every compressing min-plus digest is collision-broken in constant time.

\textbf{The failure is structural.} The collision construction never inspects the key entries: it chooses one certificate per component and increments elsewhere. Min destroys information about \emph{which} coordinate is active, but it thereby guarantees that inactive coordinates are ignored --- and ignored coordinates are free parameters for the adversary.

\textbf{Degeneracy helps the attacker.} The local invariant is $\tau(A,m) \le r$, and the maximal coordinate cone has dimension exactly $k - \tau$. Overlapping active sets reduce $\tau$ and enlarge the cone.

\textbf{Preimage resistance fails through monotonicity.} The disjunctive structure is short-circuited by a least element, even under box constraints; a proof-of-work scheme built on min-plus digests offers no work.

\textbf{Where the intuition was right.} The tropical semiring genuinely resists the linear-algebraic toolkit. The lesson is that a primitive is not secured by the absence of one attack paradigm: piecewise linear maps have their own natural analysis --- convex and polyhedral geometry --- and under that lens the min-plus digest is transparent.

\textbf{Positive readings.} Theorem~\ref{thm:local} is a clean characterisation of the invariance directions of a min-plus linear map, i.e.\ exactly the sensitivity analysis wanted for shortest-path and scheduling models: which costs may be increased without perturbing the optimum. Theorem~\ref{thm:inv} is a least-fixed-point inversion result giving an $O(rk)$ solvability test for min-plus linear systems.

\section{Open problems}

\begin{enumerate}
\item \textbf{Full recession cone.} Theorem~\ref{thm:tau} determines the maximal \emph{coordinate} cone. Is the full recession cone of the fiber cell through $m$, including non-coordinate directions, also of dimension exactly $k - \tau(A,m)$? Randomised computation supports this without exception.
\item \textbf{Complexity of the security parameter.} Is deciding $\tau(A,m) \le d$ NP-complete when $r$ is part of the input?
\item \textbf{Measure and structure of the generic locus.} The set of pairs with unique, pairwise distinct minimizers is open. Is it of full measure, and is its complement semialgebraic of computable degree?
\item \textbf{Hardness by nonce language.} Box constraints preserve tractability, as do (expectedly) difference constraints via shortest paths. Does preimage search become NP-complete once the nonce language admits arbitrary binary linear constraints, even for fixed $r$?
\item \textbf{Repaired primitives.} Does a non-monotone post-processing step restore any lost property, or does the $(k-r)$-dimensional cone survive composition?
\end{enumerate}

